namespace BlazorApp.Services;

public class Notification
{
    public int Id { get; set; }
    public string Message { get; set; } = string.Empty;
    public DateTime Timestamp { get; set; }
}

public class NotificationService
{
    private int _nextId = 1;
    private static readonly string[] SampleMessages =
    [
        "Your order has been shipped",
        "New comment on your post",
        "System maintenance scheduled",
        "Welcome to the platform!",
        "Your report is ready to download",
        "Payment received successfully",
        "New follower added",
        "Security alert: new login detected"
    ];

    public Task<List<Notification>> GetInitialNotificationsAsync()
    {
        var notifications = new List<Notification>();
        for (var i = 0; i < 3; i++)
        {
            notifications.Add(new Notification
            {
                Id = _nextId++,
                Message = SampleMessages[i],
                Timestamp = DateTime.Now.AddMinutes(-Random.Shared.Next(1, 60))
            });
        }
        return Task.FromResult(notifications);
    }

    public Task<List<Notification>> CheckForNewNotificationsAsync()
    {
        var results = new List<Notification>();
        // Simulate ~50% chance of a new notification each poll
        if (Random.Shared.Next(2) == 0)
        {
            results.Add(new Notification
            {
                Id = _nextId++,
                Message = SampleMessages[Random.Shared.Next(SampleMessages.Length)],
                Timestamp = DateTime.Now
            });
        }
        return Task.FromResult(results);
    }
}

@page "/notifications"
@rendermode InteractiveServer
@using BlazorApp.Services
@inject NotificationService NotificationService
@implements IAsyncDisposable

<PageTitle>Notifications</PageTitle>

<h1>Notifications</h1>

<span class="badge bg-primary">@(notifications?.Count ?? 0)</span>

@if (notifications is null)
{
    <p><em>Loading...</em></p>
}
else if (notifications.Count == 0)
{
    <p>No notifications.</p>
}
else
{
    <ul class="list-group mt-3">
        @foreach (var n in notifications.OrderByDescending(x => x.Timestamp))
        {
            <li class="list-group-item">
                <strong>@n.Message</strong>
                <small class="text-muted ms-2">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    private CancellationTokenSource? _cts;

    [PersistentState]
    public List<Notification>? notifications { get; set; }

    protected override async Task OnInitializedAsync()
    {
        // Only fetch if not restored from prerender state
        notifications ??= await NotificationService.GetInitialNotificationsAsync();
    }

    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            // Page is now interactive — start polling
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            try
            {
                await Task.Delay(TimeSpan.FromSeconds(5), ct);
                var newItems = await NotificationService.CheckForNewNotificationsAsync();
                if (newItems.Count > 0)
                {
                    notifications ??= new();
                    notifications.AddRange(newItems);
                    await InvokeAsync(StateHasChanged);
                }
            }
            catch (OperationCanceledException)
            {
                break;
            }
        }
    }

    public async ValueTask DisposeAsync()
    {
        if (_cts is not null)
        {
            await _cts.CancelAsync();
            _cts.Dispose();
        }
    }
}

